declare(strict_types=1);require __DIR__.'/includes/ui.php';$u=msw_require_user();msw_bot_simulation_pulse(null,4);$rows=msw_all('SELECT id,username,level,base_power,base_grade,is_bot FROM users ORDER BY base_power DESC,xp DESC,id ASC LIMIT 100');msw_header('Base Rankings','rankings.php');?>
<section class="hero"><div class="eyebrow">GLOBAL BASE POWER INDEX</div><h1>COMMANDER <span>RANKINGS</span></h1><p>Human and autonomous commanders share the same persistent Base Power ladder. Bot bases grow from real recovered staff, sector assignments, resources, dispatch activity and FOB combat rather than a fabricated ranking value.</p></section><?php msw_panel('Global Ranking','TOP 100');?><table><thead><tr><th>#</th><th>Commander</th><th>Player Lv</th><th>Grade</th><th>Base Power</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=($i+1)?></td><td><a href="<?=msw_e(msw_url('profile.php?id='.(int)$r['id']))?>" style="color:#e8d59a"><?=msw_e($r['username'])?></a> <?=((int)$r['is_bot']===1)?'<span class="ai-mark">AI</span>':''?></td><td><?=intval($r['level'])?></td><td><span class="grade"><?=msw_e($r['base_grade'])?></span></td><td><?=number_format((int)$r['base_power'])?></td></tr><?php endforeach;?></tbody></table><?php msw_panel_end();msw_footer(); ?>
